import os, glob, re

class GridLoader:
    def __init__(self):
        self.grids = {}

    def load(self):
        d = os.path.basename(os.getcwd())
        session_dir = os.path.join(os.getcwd(), d)
        jsonl_file = os.path.join(session_dir, '..', '..', '..', '..', 'sessions', d + '.jsonl')

        try:
            t = open(jsonl_file).read().replace('\\n', '\n')
            G = {}
            for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
                k, h, w = m[1], int(m[2]), int(m[3])
                rows = [r.split() for r in t[m.end():].split('\n')[:h]]
                if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                    G[k] = [[int(x) for x in r] for r in rows]
            return G
        except FileNotFoundError:
            print(f"Jsonl file not found: {jsonl_file}")
            return G

