def get_all_components(grid):
    if not grid:
        return []
    rows, cols = len(grid), len(grid[0])
    bg = grid[0][0]  # assume consistent background

    colors = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                colors.add(grid[r][c])

    all_cells = {c: [] for c in colors}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                all_cells[grid[r][c]].append((r,c))

    visited = [[False]*cols for _ in range(rows)]
    color_comps = {c: [] for c in colors}

    for color in colors:
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color and not visited[r][c]:
                    # Start flood fill
                    comp = [(r,c)]
                    stack = [(r,c)]
                    visited[r][c] = True
                    while stack:
                        cr, cc = stack.pop()
                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                                if grid[nr][nc] == color:
                                    visited[nr][nc] = True
                                    comp.append((nr,nc))
                                    stack.append((nr,nc))
                    color_comps[color].append((comp, color))

    return color_comps, bg

